  'People':{color:'#b28cff',shape:'person'},'Resources':{color:'#9bd44f',shape:'hex'},
  'Loot containers':{color:'#ffad42',shape:'box'},'Notes and recordings':{color:'#ff70bb',shape:'bookmark'},
  'Loose items':{color:'#f4dc86',shape:'dot'},'Wildlife':{color:'#ff775f',shape:'paw'},
  'Shelter and stations':{color:'#42d5cf',shape:'house'},'Breakables':{color:'#c0b8ca',shape:'cross'},
