const colors=Object.fromEntries(Object.entries(styles).map(([group,style])=>[group,style.color]));
let data,active=new Set(),visible=[],width=0,height=0,zoom=.25,center={x:2048,y:2048},player=null,world=null,feed=null,matrix=load('matrix',null),autoMatrix=null,follow=load('follow',true),trail=[],pins=load('pins',[]),hitPoints=[],query='',showLabels=load('labels',true),showTrail=load('trail',true),tiles=new Map(),drag=null,pinPosition=null,calPoints=[],recordPoint=false,selected=null,firstFix=false;
if(!validMatrix(matrix))matrix=null;
const motion=new Motion(load('smoothing',100)); let renderedYaw=0,lastFrame=performance.now();
