const screen=p=>({x:(p.x-center.x)*zoom+width/2,y:(p.y-center.y)*zoom+height/2});
const fromScreen=(x,y)=>({x:center.x+(x-width/2)/zoom,y:center.y+(y-height/2)/zoom});
function resize(){const rect=canvas.getBoundingClientRect();width=rect.width;height=rect.height;const dpr=devicePixelRatio||1;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
function setFollow(value){follow=value;const button=$('follow');button.classList.toggle('active',follow);button.setAttribute('aria-pressed',follow);button.textContent=follow?'◎ Following · map moves':'◎ Follow player';save('follow',follow);if(follow&&player)center={...player};if(feed?.status==='live')$('statusHint').textContent=follow?'Live · map moves under the centered arrow':'Live · player arrow moves on map';draw();}
