function setZoom(value,at={x:width/2,y:height/2}){const before=fromScreen(at.x,at.y);zoom=Math.max(.08,Math.min(6,value));if(follow&&player){center={...player};}else{const after=fromScreen(at.x,at.y);center.x+=before.x-after.x;center.y+=before.y-after.y;}persistView();draw();}
let drawPending=false;
