function makeFilters(){const host=$('filters');host.replaceChildren();for(const group of [...new Set(data.categories.map(c=>c.group))]){const cats=data.categories.filter(c=>c.group===group),details=document.createElement('details');details.open=['Places','Resources','Notes and recordings'].includes(group);const summary=document.createElement('summary'),dot=document.createElement('i');dot.className='swatch '+(styles[group]?.shape||'dot');dot.style.setProperty('--swatch',colors[group]);summary.append(dot,document.createTextNode(group));const count=document.createElement('span');count.className='groupCount';count.textContent=cats.reduce((s,c)=>s+c.count,0).toLocaleString();summary.append(count);details.append(summary);const row=document.createElement('div');row.className='groupButtons';for(const enabled of [true,false]){const btn=document.createElement('button');btn.textContent=enabled?'Show group':'Hide group';btn.onclick=()=>{cats.forEach(c=>enabled?active.add(c.id):active.delete(c.id));host.querySelectorAll('input').forEach(e=>e.checked=active.has(e.value));filter();};row.append(btn);}details.append(row);for(const c of cats){const label=document.createElement('label');label.className='category';const input=document.createElement('input');input.type='checkbox';input.value=c.id;input.checked=active.has(c.id);input.onchange=()=>{input.checked?active.add(c.id):active.delete(c.id);filter();};const marker=document.createElement('i');marker.className='categorySwatch';marker.style.background=categoryColor(c);const text=document.createElement('span');text.textContent=c.id==='recipe-notes'?'Recipe unlocks (labeled)':c.name;const n=document.createElement('span');n.textContent=c.count;label.append(input,marker,text,n);details.append(label);}host.append(details);}}
function showTooltip(p,s){selected=p;const tip=$('tooltip');tip.replaceChildren();const title=document.createElement('strong');title.textContent=p.name;tip.append(title);const small=document.createElement('small');small.textContent=p.pin?'Your saved pin':`${p.area||''} · ${data.categories.find(c=>c.id===p.category)?.name||''}`;tip.append(small);if(p.pin){const del=document.createElement('button');del.textContent='Remove pin';del.onclick=()=>{pins=pins.filter(v=>v.id!==p.id);save('pins',pins);tip.hidden=true;draw();};tip.append(del);}else{const link=document.createElement('a');link.textContent='Reference details ↗';link.target='_blank';link.rel='noreferrer';link.href=p.url||'https://metabot.gg/en/permafrost/map';tip.append(link);}tip.style.left=Math.min(width-290,Math.max(8,s.x+12))+'px';tip.style.top=Math.min(height-180,Math.max(65,s.y+12))+'px';tip.hidden=false;}
function pointerPos(e){const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=pointerPos(e);drag={...p,start:p,center:{...center},moved:false};canvas.setPointerCapture(e.pointerId);$('tooltip').hidden=true;});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const p=pointerPos(e);if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>4){drag.moved=true;setFollow(false);center={x:drag.center.x-(p.x-drag.start.x)/zoom,y:drag.center.y-(p.y-drag.start.y)/zoom};draw();}});
canvas.addEventListener('pointerup',e=>{if(!drag)return;const moved=drag.moved;drag=null;persistView();if(moved)return;const p=pointerPos(e);if(recordPoint){if(feed?.status!=='live'){ $('calibrationMessage').textContent='Load a character first.';return;}calPoints.push({world:{...feed.position},map:fromScreen(p.x,p.y)});recordPoint=false;if(calPoints.length===3){try{matrix=solveAffine(calPoints);save('matrix',matrix);$('calibrationMessage').textContent='Alignment saved. Live tracking is ready.';firstFix=false;poll();}catch(err){$('calibrationMessage').textContent=err.message;}calPoints=[];}$('calibrationStart').textContent=`Record point ${calPoints.length+1} of 3`;return;}const hit=hitPoints.filter(h=>Math.hypot(h.s.x-p.x,h.s.y-p.y)<h.r).sort((a,b)=>Math.hypot(a.s.x-p.x,a.s.y-p.y)-Math.hypot(b.s.x-p.x,b.s.y-p.y))[0];if(hit)showTooltip(hit.p,p);});
canvas.addEventListener('pointercancel',()=>drag=null);
canvas.addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom*Math.exp(-e.deltaY*.0015),pointerPos(e));},{passive:false});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();const p=pointerPos(e);pinPosition=fromScreen(p.x,p.y);$('pinEditor').hidden=false;$('pinName').value='';$('pinName').focus();});
canvas.addEventListener('keydown',e=>{if(e.key==='+'||e.key==='=')setZoom(zoom*1.3);if(e.key==='-')setZoom(zoom/1.3);});
$('pinSave').onclick=()=>{const name=$('pinName').value.trim();if(!name)return;pins.push({...pinPosition,name,id:crypto.randomUUID()});save('pins',pins);$('pinEditor').hidden=true;draw();};$('pinCancel').onclick=()=>$('pinEditor').hidden=true;
$('follow').onclick=()=>setFollow(!follow);$('fit').onclick=fit;$('zoomIn').onclick=()=>setZoom(zoom*1.3);$('zoomOut').onclick=()=>setZoom(zoom/1.3);$('search').oninput=e=>{query=e.target.value.trim().toLowerCase();filter();};
$('all').onclick=()=>{active=new Set(data.categories.map(c=>c.id));makeFilters();filter();};$('none').onclick=()=>{active.clear();makeFilters();filter();};$('defaults').onclick=()=>{active=new Set(data.categories.filter(c=>c.default).map(c=>c.id));makeFilters();filter();};
$('sidebarToggle').onclick=()=>{document.body.classList.toggle('collapsed');resize();};$('fullscreen').onclick=async()=>{if(window.chrome?.webview){window.chrome.webview.postMessage('fullscreen');return;}if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();};
$('labels').checked=showLabels;$('trail').checked=showTrail;$('labels').onchange=e=>{showLabels=e.target.checked;save('labels',showLabels);draw();};$('trail').onchange=e=>{showTrail=e.target.checked;save('trail',showTrail);draw();};$('clearTrail').onclick=()=>{trail=[];draw();};$('dismissWelcome').onclick=()=>$('welcome').hidden=true;
$('calibrationButton').onclick=()=>{$('calibration').hidden=!$('calibration').hidden;};$('calibrationClose').onclick=()=>{$('calibration').hidden=true;recordPoint=false;};$('calibrationStart').onclick=()=>{if(feed?.status!=='live'){$('calibrationMessage').textContent='Load your character before recording a point.';return;}recordPoint=true;setFollow(false);$('calibrationMessage').textContent='Click where your character is standing on the map.';};$('calibrationReset').onclick=()=>{matrix=null;save('matrix',null);calPoints=[];firstFix=false;$('calibrationMessage').textContent='Using game-provided alignment when available.';$('calibrationStart').textContent='Record point 1 of 3';};
let polling=false;
async function poll(){if(polling)return;polling=true;try{const response=await fetch('api/position',{cache:'no-store',signal:AbortSignal.timeout(2500)});if(!response.ok)throw Error('Feed unavailable');const next=await response.json();feed=next;autoMatrix=validMatrix(next.mapMatrix)?next.mapMatrix:null;const m=transform();
  if(next.status==='live'&&next.position){if(world!==next.world){trail=[];world=next.world;firstFix=false;}const snapped=motion.push(next,performance.now()); if(snapped){trail=[];firstFix=false;} const pose=motion.at(performance.now()); player=m&&pose?project(pose.position,m):null; if(pose)renderedYaw=pose.yaw; if(snapped&&player&&follow)center={...player};$('status').textContent=player?'Player connected':'Position connected';$('statusDot').classList.add('live');$('statusHint').textContent=player?(follow?'Live · map moves under the centered arrow':'Live · player arrow moves on map'):'Waiting for map alignment';$('coords').textContent=`X ${next.position.x.toFixed(0)}  Y ${next.position.y.toFixed(0)}  Z ${next.position.z.toFixed(0)}`;if(player){if(!firstFix){firstFix=true;if(follow)zoom=Math.max(zoom,.8);}if(!trail.length||Math.hypot(player.x-trail.at(-1).x,player.y-trail.at(-1).y)>1){if(trail.length&&Math.hypot(player.x-trail.at(-1).x,player.y-trail.at(-1).y)>500)trail=[];trail.push({...player});if(trail.length>1500)trail.shift();}$('welcome').hidden=true;}else{$('welcomeText').textContent='Position is connected. Automatic alignment needs the final mod update, or use Align map to record three reference points.';}}
  else{motion.reset();player=null;firstFix=false;$('statusDot').classList.remove('live');const states={waiting_for_game:'Waiting for Permafrost',disconnected:'Permafrost is closed',waiting_for_player:'Load your character',starting:'Game starting',read_error:'Position read error',position_unavailable:'Position unavailable'};$('status').textContent=states[next.status]||'Waiting for player';$('statusHint').textContent=next.status==='disconnected'?'Open Permafrost and load a character':'Map exploration remains available';$('coords').textContent='Position —';}
  $('alignment').textContent=matrix?'Manual alignment':autoMatrix?'Game map alignment':'Alignment awaiting game';draw();
}catch{motion.reset();firstFix=false;$('status').textContent='Companion offline';$('statusHint').textContent='Run Start Live Map.cmd to reconnect';$('statusDot').classList.remove('live');player=null;draw();}finally{polling=false;}}
try{const response=await fetch('data/map.json');if(!response.ok)throw Error('Map data missing');data=await response.json();active=new Set(load('active',data.categories.filter(c=>c.default).map(c=>c.id)));makeFilters();filter();new ResizeObserver(resize).observe($('mapArea'));resize();const view=load('view',null);if(view&&Number.isFinite(view.zoom)&&view.center){center=view.center;zoom=view.zoom;}else{center={x:1740,y:1080};zoom=Math.min(width/2800,height/2500);}setFollow(follow);await poll();setInterval(poll,50);}catch(err){$('status').textContent='Map could not load';$('statusHint').textContent=err.message;}

function animate(now){
 const dt=Math.min(.1,(now-lastFrame)/1000);lastFrame=now;
 const pose=motion.at(now),m=transform();
 if(pose&&m&&feed?.status==='live'){
   player=project(pose.position,m);renderedYaw=pose.yaw;
   if(follow){const distance=Math.hypot(player.x-center.x,player.y-center.y)*zoom;const tau=distance>150?.045:.09;const k=1-Math.exp(-dt/tau);center.x+=(player.x-center.x)*k;center.y+=(player.y-center.y)*k;}
   draw();
 }else if(player&&!pose){player=null;firstFix=false;$('status').textContent='Position feed stalled';$('statusDot').classList.remove('live');draw();}
 requestAnimationFrame(animate);
}
requestAnimationFrame(animate);
const smoothing=$('smoothing');smoothing.value=motion.delay;$('smoothingValue').textContent=motion.delay+' ms';
smoothing.oninput=()=>{motion.delay=Number(smoothing.value);save('smoothing',motion.delay);$('smoothingValue').textContent=motion.delay+' ms';};
const theme=$('theme'),accent=$('accent'),background=$('background');
theme.value=load('theme','default');accent.value=load('accent','#e850b5');background.value=load('background','#161226');
function applyTheme(){const custom=theme.value==='custom',nomad=theme.value==='nomad';document.documentElement.style.setProperty('--accent',custom?accent.value:nomad?'#e850b5':'#69dec9');document.documentElement.style.setProperty('--bg',custom?background.value:nomad?'#161226':'#101c25');accent.hidden=background.hidden=!custom;save('theme',theme.value);save('accent',accent.value);save('background',background.value);if(window.chrome?.webview){const css=getComputedStyle(document.documentElement);window.chrome.webview.postMessage('theme:'+css.getPropertyValue('--accent').trim()+':'+css.getPropertyValue('--bg').trim());}}
theme.onchange=accent.oninput=background.oninput=applyTheme;applyTheme();
document.addEventListener('keydown',e=>{if(window.chrome?.webview&&(e.key==='F11'||e.key==='Escape')){e.preventDefault();window.chrome.webview.postMessage(e.key==='Escape'?'escape':'fullscreen');}});

